-- Programme content fixes (27/11). Each runs only while the record still has the old text, so later edits from the dashboard stay.

-- id 1: the title is «دبلوم ادارة التمريض» but the address, summary and outcomes were still those of business administration.
-- Content now matches the diploma's name; the old address redirects (web/public/seo.php, moved slugs).
UPDATE programs SET title = 'دبلوم إدارة التمريض', slug = 'دبلوم-إدارة-التمريض', summary = 'دبلوم إدارة التمريض يؤهل الممرضين والممرضات والعاملين في القطاع الصحي لقيادة أقسام التمريض وإدارتها بكفاءة: تخطيط الرعاية التمريضية، وإدارة فرق العمل والمناوبات، وضمان جودة الرعاية وسلامة المرضى، وفق أنظمة القطاع الصحي في المملكة.', body = '<h3>ما الذي سيتعرف عليه المتدرب؟</h3><ul><li>فهم أسس الإدارة والقيادة في التمريض، ووظائفها: التخطيط، والتنظيم، والتوجيه، والرقابة داخل أقسام التمريض</li><li>تخطيط القوى العاملة التمريضية وتوزيع المهام والمناوبات وتقييم أداء الكوادر</li><li>تطبيق معايير جودة الرعاية الصحية وسلامة المرضى ومكافحة العدوى</li><li>إدارة الموارد والمستلزمات الطبية وميزانية القسم بكفاءة</li><li>مهارات التواصل الفعّال مع الفريق الصحي والمرضى وذويهم، وإدارة الأزمات وضغوط العمل</li><li>الإلمام بأخلاقيات المهنة والأنظمة واللوائح المنظمة للعمل الصحي في المملكة</li></ul>', features = '["المدة: سنتين ونصف", "المستويات: ثمانية مستويات", "عدد المقررات: 32", "فهم أسس الإدارة والقيادة في التمريض، ووظائفها: التخطيط، والتنظيم، والتوجيه، والرقابة داخل أقسام التمريض", "تخطيط القوى العاملة التمريضية وتوزيع المهام والمناوبات وتقييم أداء الكوادر", "تطبيق معايير جودة الرعاية الصحية وسلامة المرضى ومكافحة العدوى", "إدارة الموارد والمستلزمات الطبية وميزانية القسم بكفاءة", "مهارات التواصل الفعّال مع الفريق الصحي والمرضى وذويهم، وإدارة الأزمات وضغوط العمل", "الإلمام بأخلاقيات المهنة والأنظمة واللوائح المنظمة للعمل الصحي في المملكة"]'
WHERE id = 1 AND slug = 'دبلوم-ادارة-الأعمال';

-- English course: its summary was copied from «دورة الإدارة المكتبية المتقدمة»
UPDATE programs SET summary = 'دورة اللغة الإنجليزية تطوّر مهارات المحادثة والاستماع والقراءة والكتابة، وتبني المفردات والقواعد التي تحتاجها في الدراسة وبيئة العمل، بأسلوب تطبيقي يناسب جميع المستويات.'
WHERE id = 9 AND summary LIKE 'دورة موسعة تمنحك مهارات إدارية متقدمة%';

